{"file_path":"C:\Users\scott\Documents\HaloTodoPromptOnly/public/styles.css","content":"* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    min-height: 100vh;
    padding: 20px;
}

.container {
    max-width: 600px;
    margin: 0 auto;
}

header {
    text-align: center;
    margin-bottom: 30px;
    color: white;
}

header h1 {
    font-size: 2.5rem;
    text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.3);
}

.todo-app {
    background: white;
    border-radius: 10px;
    padding: 25px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
}

.input-section {
    display: flex;
    gap: 10px;
    margin-bottom: 20px;
}

#todo-input {
    flex: 1;
    padding: 15px;
    border: 2px solid #e1e5e9;
    border-radius: 5px;
    font-size: 1rem;
    outline: none;
    transition: border-color 0.3s;
}

#todo-input:focus {
    border-color: #667eea;
}

#add-btn {
    padding: 15px 25px;
    background: #667eea;
    color: white;
    border: none;
    border-radius: 5px;
    cursor: pointer;
    font-size: 1rem;
    font-weight: bold;
    transition: background 0.3s;
}

#add-btn:hover {
    background: #5a6fd8;
}

.filters {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 20px;
    flex-wrap: wrap;
    gap: 10px;
}

.filter-btn {
    padding: 8px 15px;
    background: #f0f0f0;
    border: none;
    border-radius: 5px;
    cursor: pointer;
    font-size: 0.9rem;
    transition: all 0.3s;
}

.filter-btn.active,
.filter-btn:hover {
    background: #667eea;
    color: white;
}

#clear-completed {
    margin-left: auto;
    padding: 8px 15px;
    background: #ff6b6b;
    color: white;
    border: none;
    border-radius: 5px;
    cursor: pointer;
    font-size: 0.9rem;
    transition: background 0.3s;
}

#clear-completed:hover {
    background: #ff5252;
}

.todo-list {
    list-style-type: none;
}

.todo-item {
    display: flex;
    align-items: center;
    padding: 15px;
    border-bottom: 1px solid #eee;
    transition: background 0.3s;
}

.todo-item:last-child {
    border-bottom: none;
}

.todo-item:hover {
    background-color: #f9f9f9;
}

.todo-checkbox {
    margin-right: 15px;
    width: 20px;
    height: 20px;
    cursor: pointer;
}

.todo-text {
    flex: 1;
    font-size: 1.1rem;
    word-break: break-word;
}

.todo-text.completed {
    text-decoration: line-through;
    color: #888;
}

.delete-btn {
    margin-left: 15px;
    padding: 8px 12px;
    background: #ff6b6b;
    color: white;
    border: none;
    border-radius: 3px;
    cursor: pointer;
    font-size: 0.9rem;
    transition: background 0.3s;
}

.delete-btn:hover {
    background: #ff5252;
}

.empty-state {
    text-align: center;
    padding: 40px 20px;
    color: #888;
    font-style: italic;
}

@media (max-width: 600px) {
    .container {
        margin: 0;
        padding: 10px;
    }

    header h1 {
        font-size: 2rem;
    }

    .todo-app {
        padding: 20px;
    }

    .input-section {
        flex-direction: column;
    }

    #add-btn {
        width: 100%;
    }

    .filters {
        justify-content: center;
    }

    #clear-completed {
        margin-left: 0;
    }
}"}

